INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.mb.contingency.differentiation', 'mb.contingency', 'تحلیل تمایز و یکپارچگی لارنس و لورش', 'توانایی تشخیص الزامات ساختاری سازمان در مواجهه با عدم‌قطعیت محیطی از طریق ترکیب مناسب زیرسیستم‌های تمایزیافته با سازوکارهای یکپارچه‌ساز قوی.', 'Analysis', 4, 70, '45', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.mb.structure.mechanic_organic', 'mb.structure', 'تمایز ساختارهای مکانیکی و ارگانیک برنز و استاکر', 'توانایی تطبیق مشخصات ساختاری (رسمیت، تمرکز، سلسله‌مراتب) با درجه ثبات یا پویایی محیط سازمان.', 'Comprehension', 2, 50, '30', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.stats.anova.parametric_assumptions', 'stats.anova', 'اجرا و بررسی مفروضات تحلیل واریانس (ANOVA)', 'توانایی تشخیص ضرورت آزمون F برای مقایسه بیش از دو گروه مستقل، آزمون همسانی واریانس لون و نرمال بودن باقیمانده‌ها.', 'Analysis', 4, 75, '50', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.stats.scales.identify', 'stats.scales', 'تشخیص و تمایز مقیاس‌های چهارگانه اندازه‌گیری آماری', 'توانایی شناسایی صحیح مقیاس‌های اسمی، ترتیبی، فاصله‌ای و نسبتی در متغیرهای پژوهش مدیریت.', 'Knowledge', 1, 35, '25', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.sm.rbv.vrio', 'sm.rbv', 'ارزیابی منابع سازمانی با چارچوب VRIO جی بارنی', 'توانایی طبقه‌بندی منابع سازمان در ابعاد ارزش، کمیابی، تقلیدناپذیری و سازمان‌یافتگی جهت تعیین مزیت رقابتی پایدار یا موقت.', 'Evaluation', 5, 80, '50', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.sm.value_chain.porter', 'sm.value_chain', 'تحلیل زنجیره ارزش پورتر و تفکیک فعالیت‌های اولیه و پشتیبانی', 'شناسایی ۵ فعالیت اصلی و ۴ فعالیت پشتیبانی زنجیره ارزش و پیوند آن‌ها با حاشیه سود و مزیت تمایز یا بهای تمام‌شده.', 'Analysis', 4, 60, '40', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.mkt.brand.cbbe_pyramid', 'mkt.brand', 'تحلیل هرم دارایی ویژه برند کلر (CBBE)', 'توانایی تشریح ۴ لایه و ۶ بلوک هرم کلر از برجستگی، عملکرد و تصویر تا قضاوت، احساسات و رزونانس نهایی برند.', 'Analysis', 4, 75, '50', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.inno.s_curve.disruption', 'inno.s_curve', 'منحنی S فناوری و نقاط گذار پارادایم تکنولوژیک', 'تحلیل بازده نزولی فناوری‌های موجود در فاز اشباع و زمان‌بندی سرمایه‌گذاری روی فناوری نوظهور نسل بعدی.', 'Evaluation', 5, 80, '50', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.inno.ambidextrous.dual_focus', 'inno.ambidextrous', 'مدیریت سازمان‌های دوپهلو (Ambidexterity)', 'تحلیل ساختاری ترکیب هم‌زمان واحدهای بهره‌برداری (Exploitation) و اکتشاف (Exploration) تحت هدایت راهبردی مشترک.', 'Analysis', 4, 75, '45', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.tech.absorptive.capacity', 'tech.absorptive', 'ظرفیت جذب دانش کوهن و لوینتال', 'تحلیل سه مؤلفه شناسایی، یکپارچه‌سازی و کاربست تجاری دانش بیرونی و وابستگی آن به سرمایه‌گذاری قبلی تحقیق و توسعه.', 'Comprehension', 2, 65, '40', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.mkt.plc.stages', 'mkt.plc', 'تحلیل مراحل چرخه عمر محصول (PLC) و راهبردهای بازاریابی متناسب با هر مرحله', 'توانایی تشخیص مرحلهٔ جاری محصول (معرفی، رشد، بلوغ، افول) از روی شاخص‌های فروش و سود و انتخاب آمیزهٔ بازاریابی متناسب با هر مرحله', 'Analysis', 4, 65, '35', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.sm.portfolio.bcg_ge', 'sm.portfolio', 'تحلیل سبد کسب‌وکار با ماتریس‌های رشد-سهم (BCG) و جذابیت-توانمندی جنرال الکتریک (GE)', 'توانایی طبقه‌بندی واحدهای کسب‌وکار در ماتریس‌های BCG و GE و استخراج راهبرد تخصیص منابع متناسب با هر خانهٔ ماتریس', 'Analysis', 4, 70, '45', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.sm.rbv.isolating_mechanisms', 'sm.rbv', 'تحلیل مکانیسم‌های انزوا، نایافت‌پذیری و تقلیدناپذیری در تئوری منبع‌محور (RBV) بارنی', 'توانایی شناسایی مکانیسم‌های انزوا (مسیر وابستگی، ابهام علّی، پیچیدگی اجتماعی و...) که تداوم مزیت رقابتی را در چارچوب VRIN/VRIO تضمین می‌کنند', 'Evaluation', 5, 75, '50', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
INSERT INTO skills (id, node_id, title, operational_definition, cognitive_level, bloom_level, difficulty_estimate, estimated_study_minutes, verification_status) VALUES ('skill.ind.or_simplex', 'ind.or_simplex', 'تحقیق در عملیات: روش سیمپلکس، دوگان و تحلیل حساسیت', 'توانایی محاسبه و تفسیر قیمت سایه، قضایای دوگانگی و قضایای انطباق مکمل در برنامه‌ریزی خطی', 'Application', 3, 75, '50', 'unverified') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, operational_definition = EXCLUDED.operational_definition, cognitive_level = EXCLUDED.cognitive_level, bloom_level = EXCLUDED.bloom_level, difficulty_estimate = EXCLUDED.difficulty_estimate, estimated_study_minutes = EXCLUDED.estimated_study_minutes;
