INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-001', 'sm.rbv', 1401, 'کدام گزینه، ویژگی‌های منبع استراتژیک در مدل بارنی را به‌طور کامل توصیف می‌کند؟', '["ارزش‌مند، کمیاب، تقلیدناپذیر و جایگزینی‌ناپذیر","فراوان، ارزان و در دسترس","قابل کپی، ملموس و قابل معامله","شهودی، ملموس و ماندگار"]'::jsonb, 0, 'مدل VRIN بارنی: منبع باید ارزش‌آفرین، کمیاب، تقلیدناپذیر و بدون جایگزین باشد تا مزیت پایدار بسازد.', 'دام رایج طراح: جایگزینی «جایگزینی‌ناپذیر» با «قابل معامله» یا خلط VRIN با VRIO.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
