INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-002', 'sm.rbv', 1403, 'قابلیت‌های پویا (تیس) عمدتاً برای برطرف‌کردن کدام محدودیتِ دیدگاه مبتنی بر منابع مطرح شدند؟', '["سکون قابلیت‌ها در محیط‌های به‌سرعت متغیر","تأکید بیش از حد بر مشتری","نادیده‌گرفتن هزینهٔ تولید","تمرکز بر بازارهای محلی"]'::jsonb, 0, 'قابلیت‌های پویا یعنی توان بازآرایی و بازشکل‌دهی شایستگی‌ها برای پاسخ به تغییرات محیطی.', 'دام: گزینه‌هایی که «بازآرایی منابع در محیط متغیر» را با «کاهش هزینه» اشتباه می‌گیرند.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
