INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-003', 'sm.value_chain', 1400, 'در زنجیرهٔ ارزش پورتر، فعالیت‌های «حاشیه‌ساز» کدام‌اند؟', '["زیرساخت سازمان، مدیریت منابع انسانی، توسعهٔ فناوری و خرید","ورودی‌ها، عملیات، خروجی‌ها، بازاریابی و فروش و خدمات","فقط بازاریابی و فروش","فقط عملیات و خدمات"]'::jsonb, 0, 'فعالیت‌های اصلی مستقیماً محصول/خدمت را می‌سازند؛ حاشیه‌سازها از همهٔ فعالیت‌ها پشتیبانی می‌کنند.', 'دام کلاسیک: جابه‌جایی فهرست فعالیت‌های اصلی و حاشیه‌ساز.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
