INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-014', 'tech.absorptive', 1403, 'ظرفیت جذب (Absorptive Capacity) بر اساس تعریف کوهن و لوینتال چیست؟', '["توانایی شناسایی، جذب و کاربست دانش بیرونی","میزان سرمایهٔ ثابت شرکت","تعداد پتنت‌های ثبت‌شده","سرعت تولید محصول"]'::jsonb, 0, 'ظرفیت جذب تابع دانش قبلی مرتبط سازمان است و سه مؤلفهٔ شناسایی، جذب و کاربست دارد.', 'دام: تعریف ظرفیت جذب به‌صورت موجودی دارایی به‌جای توانایی فرایندی.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
