INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-015', 'ind.or_simplex', 1402, 'در قضیه دوگانگی برنامه‌ریزی خطی، متناظر با متغیر کمکی (Slack) که در جواب بهینه اولیه مقدار اکیداً مثبت دارد، متغیر دوگان متناظر چه وضعیتی دارد؟', '["الزاماً برابر صفر است (قضیه انطباق مکمل)","الزاماً مثبت است","برابر ضریب تابع هدف اولیه است","نامحدود در علامت است"]'::jsonb, 0, 'بر اساس قضیه انطباق مکمل (Complementary Slackness)، اگر متغیر کمکی در مسئله اولیه مثبت باشد، متغیر دوگان متناظر حتماً صفر است.', 'دام: خلط بین قیمت سایه مثبت با قضیه مکمل بودن متغیر کمکی مثبت و متغیر دوگان صفر.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
