INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-016', 'ind.mcdm', 1403, 'تفاوت بنیادین روش‌های TOPSIS و VIKOR در تصمیم‌گیری چندمعیاره (MADM) چیست؟', '["TOPSIS از فاصله اقلیدسی نسبت به نقاط ایده‌آل استفاده می‌کند، اما VIKOR بر اساس مفهوم سازش خطی و بیشترین مطلوبیت گروهی عمل می‌کند","TOPSIS برای متغیرهای کیفی است و VIKOR صرفاً برای متغیرهای کمی","TOPSIS نیاز به ماتریس مقایسات زوجی دارد ولی VIKOR نیازی به وزن‌دهی ندارد","در VIKOR نرخ ناسازگاری ماتریس کنترل می‌شود اما در TOPSIS امکان‌پذیر نیست"]'::jsonb, 0, 'تاپسیس گزینه‌ای را انتخاب می‌کند که کمترین فاصله اقلیدسی از ایده آل مثبت و بیشترین فاصله از ایده آل منفی را دارد، درحالی‌که ویکور بر اساس سنجه سازش خطی رتبه‌بندی می‌کند.', 'دام: اشتباه گرفتن مقایسات زوجی AHP با محاسبات برداری تاپسیس و ویکور.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
