INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-017', 'ind.production_inv', 1401, 'در مدل پایه مقدار اقتصادی سفارش (EOQ)، در نقطه بهینه کدام رابطه همواره برقرار است؟', '["کل هزینه سالانه سفارش‌دهی برابر با کل هزینه سالانه نگهداری موجودی است","هزینه نگهداری به صفر می‌رسد","تعداد سفارشات در سال به حداکثر می‌رسد","هزینه خرید کالا با هزینه راه‌اندازی برابر می‌شود"]'::jsonb, 0, 'در مشتق‌گیری فرمول هریس-ویلسون (EOQ)، نقطه بهینه در محل تقاطع هزینه‌های سفارش‌دهی و هزینه‌های نگهداری رخ می‌دهد (Holding Cost = Ordering Cost).', 'دام: خلط هزینه خرید کل کالا با هزینه‌های متغیر نگهداری و سفارش‌دهی.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
