INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_pack_id, exam_level, content_origin) VALUES ('demo-q-018', 'ind.supply_chain', 1404, 'کدام راهکار مؤثرترین نقش را در مهار پدیده «اثر شلاق چرمی» (Bullwhip Effect) در زنجیره تأمین ایفا می‌کند؟', '["اشتراک‌گذاری برخط داده‌های نقطه فروش (POS) و اجرای موجودی مدیریت‌شده توسط فروشنده (VMI)","افزایش حجم دسته‌های سفارش برای کاهش هزینه‌های حمل","افزایش تخفیف‌های فصلی و فروش مقطعی به عمده‌فروشان","افزایش زمان تدارک (Lead Time) در سراسر شبکه"]'::jsonb, 0, 'پدیده شلاق چرمی در اثر اعوجاج اطلاعات تقاضا در طول زنجیره تشدید می‌شود. اشتراک‌گذاری برخط داده‌های POS و پیاده‌سازی سیستم VMI مانع از انباشت خطای پیش‌بینی می‌شود.', 'دام: سفارش‌دهی دسته‌ای و تخفیف‌های مقطعی خود از عوامل اصلی تشدید اثر شلاق چرمی هستند نه مهار آن.', 'demo', 'demo-pack-phd-management', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_option = EXCLUDED.correct_option, exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
